							goto case 1;

						goto case 0;

					case 3:
						// Hex{1,4} — take another, or leave stopping open
						if (c0 >= 4)
						{
							saved = c0;
							goto case 2;
						}

						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 2; bt[sp + 1] = p; bt[sp + 2] = c0; sp += 3;
						goto case 6;

					case 4:
						// Hex{1,4} — one more taken
						c0++;
						goto case 3;

					case 5:
						// Hex{1,4} — start counting
						c0 = 0;
						goto case 3;

					case 6:
						// Hex
						r = Recognize_Hex(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					default:
						return -1;
				}
			}
		}

